// Met la série au format attendu par le site (src/services/marketData.ts).
const lignes = $input.all().map((i) => i.json).filter((r) => r.semaine);
const derniere = lignes.at(-1) ?? {};
return [{
  json: {
    produit: 'mangue',
    marche: derniere.marches || 'Rungis',
    unite: '€/kg',
    source: 'RNM FranceAgriMer, cotations grossistes saisies chaque semaine',
    points: lignes.map((r) => ({ semaine: r.semaine, prix: Number(r.prix) })),
    commentaire: derniere.commentaire ?? null,
    majLe: derniere.derniere_date ?? null, // date de la dernière cotation (AAAA-MM-JJ)
    exemple: false,
  },
}];
